using Microsoft.Data.SqlClient; using Sales.DTO; using System.Data;
namespace Sales.DAL;
public sealed class SalesRepository {
 public async Task<int> CheckoutAsync(int employeeId,int? customerId,IReadOnlyCollection<CartItem> items){if(items.Count==0)throw new InvalidOperationException("Giỏ hàng đang trống.");
  if(employeeId<=0)throw new ArgumentException("Nhân viên không hợp lệ.");
  if(items.Any(x=>string.IsNullOrWhiteSpace(x.MaSP)||x.SoLuong<=0))throw new ArgumentException("Sản phẩm hoặc số lượng trong giỏ không hợp lệ.");
  await using var c=Db.CreateConnection(); await c.OpenAsync(); await using var tx=(SqlTransaction)await c.BeginTransactionAsync(); try { decimal total=0; var lines=new List<(string id,int qty,decimal price)>(); foreach(var item in items.GroupBy(x=>x.MaSP)){int qty=item.Sum(x=>x.SoLuong); await using var p=new SqlCommand("SELECT GiaBan FROM SanPham WHERE MaSP=@id",c,tx);p.Parameters.AddWithValue("@id",item.Key);var value=await p.ExecuteScalarAsync();if(value is null)throw new InvalidOperationException($"Khong tim thay san pham {item.Key}.");decimal price=Convert.ToDecimal(value);lines.Add((item.Key,qty,price));total+=price*qty;}
 await using var h=new SqlCommand("INSERT INTO HoaDon(MaNV,MaKH,TongTien) OUTPUT INSERTED.MaHD VALUES(@nv,@kh,@total)",c,tx);h.Parameters.AddWithValue("@nv",employeeId);h.Parameters.AddWithValue("@kh",(object?)customerId??DBNull.Value);h.Parameters.AddWithValue("@total",total);int id=Convert.ToInt32(await h.ExecuteScalarAsync());
 foreach(var line in lines){await using var stock=new SqlCommand("UPDATE SanPham SET SoLuongTon=SoLuongTon-@q WHERE MaSP=@id AND SoLuongTon>=@q",c,tx);stock.Parameters.AddWithValue("@q",line.qty);stock.Parameters.AddWithValue("@id",line.id);if(await stock.ExecuteNonQueryAsync()!=1)throw new InvalidOperationException($"San pham {line.id} khong du ton kho.");await using var detail=new SqlCommand("INSERT INTO ChiTietHoaDon(MaHD,MaSP,SoLuong,DonGia) VALUES(@hd,@sp,@q,@price)",c,tx);detail.Parameters.AddWithValue("@hd",id);detail.Parameters.AddWithValue("@sp",line.id);detail.Parameters.AddWithValue("@q",line.qty);detail.Parameters.AddWithValue("@price",line.price);await detail.ExecuteNonQueryAsync();}
 if(customerId.HasValue){await using var pts=new SqlCommand("UPDATE KhachHang SET DiemTichLuy=DiemTichLuy+CONVERT(INT,FLOOR(@total/100000.0)) WHERE MaKH=@kh",c,tx);pts.Parameters.AddWithValue("@total",total);pts.Parameters.AddWithValue("@kh",customerId.Value);if(await pts.ExecuteNonQueryAsync()!=1)throw new InvalidOperationException("Khach hang khong ton tai.");}
 await tx.CommitAsync();return id; } catch {await tx.RollbackAsync();throw;} }
 public async Task<decimal> RevenueAsync(DateTime from,DateTime to){await using var c=Db.CreateConnection();await c.OpenAsync();await using var cmd=new SqlCommand("SELECT COALESCE(SUM(TongTien),0) FROM HoaDon WHERE NgayLap>=@f AND NgayLap<@t",c);cmd.Parameters.AddWithValue("@f",from);cmd.Parameters.AddWithValue("@t",to);return Convert.ToDecimal(await cmd.ExecuteScalarAsync());}
 public async Task<DataTable> TopProductsAsync(){var t=new DataTable();await using var c=Db.CreateConnection();await c.OpenAsync();await using var cmd=new SqlCommand("SELECT TOP 5 sp.MaSP,sp.TenSP,SUM(ct.SoLuong) AS TongSoLuong FROM ChiTietHoaDon ct JOIN SanPham sp ON sp.MaSP=ct.MaSP GROUP BY sp.MaSP,sp.TenSP ORDER BY TongSoLuong DESC",c);await using var r=await cmd.ExecuteReaderAsync();t.Load(r);return t;}
}
